assignments.value:
={{
  Number($('Calculate Fixed Scores').item.json.budget_points)
  + Number($('Calculate Fixed Scores').item.json.timeline_points)
  + Number($json.output.business_need_points)
  + Number($json.output.company_fit_points)
  + Number($json.output.buying_intent_points)
}}

={{
(() => {
  const budget = $json.budget;

  if (budget === '10000+') return 25;
  if (budget === '5000-10000') return 22;
  if (budget === '3000-5000') return 18;
  if (budget === '1000-3000') return 10;
  if (!budget || budget === 'Unknown') return 5;

  return 2;
})()
}}

={{
(() => {
  const timeline = $json.timeline;

  if (timeline === 'ASAP') return 20;
  if (timeline === 'Within 30 days') return 18;
  if (timeline === '1-3 months') return 14;
  if (timeline === '3-6 months') return 8;
  if (timeline === 'Just exploring') return 3;

  return 0;
})()
}}
